contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function that drives c and asserts the property.
    function check_forward_all(uint256 amount) public payable {
        // We require this contract has enough balance to send the requested amount
        require(address(this).balance >= amount);

        // Call go sending `amount` wei which should be forwarded to owner by the original contract.
        c.go{value: amount}();

        // The distinguishing property: after go, the contract's balance must be zero.
        // This holds for the original (which forwards remaining balance to owner) but can be violated if the external call consumes behavior changes and leaves balance.
        assert(address(c).balance == 0);
    }

    // Allow funding this test contract so it can call c.go with ETH
    receive() external payable {}
}

