contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        try c.go{value: amount}() { reverted = false; } catch { reverted = true; }
        // In the original, if the external call from C to target fails, go() reverts.
        // We cannot observe target directly, but we can detect failure by comparing post-call balances:
        // If C had nonzero balance before the transfer to owner (i.e., if the external call failed and funds remained),
        // the original reverts and thus reverted == true. The mutant ignores the failure and does not revert.
        // We assert that any call that did NOT succeed (reverted == true) cannot happen when the call would have succeeded;
        // equivalently we assert: if the call did not revert then it must have completed successfully (reverted == false).
        // More directly: require that reverted == true implies the call reverted (this is tautological), but we need a rule
        // that the original enforces and the mutant breaks: original always reverts when external call fails, meaning
        // whenever the call would have left C with nonzero balance it must revert. We detect this by asserting that
        // if the call did NOT revert, then C's balance is zero (funds forwarded). This holds for original but fails for mutant.
        assert(!reverted == (address(c).balance == 0));
    }
    receive() external payable { }
}

