contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        uint before = address(this).balance;
        bool reverted; try c.go{value: amount}() { reverted = false; } catch { reverted = true; }
        uint after = address(this).balance;
        // In the original, if go does not revert then the forwarded call succeeded and C forwarded all funds to owner,
        // so C's balance is 0 and the caller has spent exactly `amount` (minus any gas), i.e. after < before.
        // The mutant allows go to succeed while ignoring a failed external call, which can leave funds in C and
        // not reduce the caller's balance as expected by the original behavior. We assert that if call did not revert,
        // then C's balance is zero and the caller's balance decreased (spent the sent amount).
        assert(reverted || (address(c).balance == 0 && after < before));
    }
    receive() external payable { }
}

