contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address payer) public {
        // keep amount in a reasonable range but allow 0..large
        amount = bound(amount, 0, 1 ether);
        // deploy an adversarial callee that ALWAYS reverts on receiving ETH
        Reverter rev = new Reverter();

        // Fund the payer so they can send ETH
        vm.deal(payer, amount);
        // The contract C has hardcoded target address; we need to trick it by
        // creating a call path: since C calls a fixed address, we cannot change that address.
        // However the observable difference hinges on whether the external call fails.
        // To force failure, we send to a recipient that will revert within the call path.
        // Because C calls a fixed address in source, we cannot change that at runtime.
        // Instead, we simulate behavior by making the call from the payer to C, and ensure
        // that when C performs its internal call to the fixed target, that call will revert.
        // The only way to ensure that in test is to have the target address be a contract that reverts.
        // Since the target in source is a concrete address, we cannot overwrite it here,
        // but the mutation we're testing is about ignoring a failing external call. To trigger a failing
        // external call we need the target to revert; in the test environment we assume the target
        // at that hardcoded address is controlled and will revert. To enforce the adversarial behavior
        // we deploy a Reverter and ensure the call to c.go() carries 0 value so C's low-level call will
        // not succeed in transferring funds (the mutant may differ). However, since we must not rely on
        // external state, we instead assert the universal property that after go(), address(c).balance == 0
        // for the correct contract. We invoke c.go() from the fuzzed payer sending the fuzzed amount.

        // Call go() as payer with value amount
        vm.prank(payer);
        // If amount is zero, still call to cover that case
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("go()"));
        // The reference contract always forwards its balance to owner, so address(c).balance should be 0
        assertTrue(address(c).balance == 0);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
}

