            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: for the reference implementation, regardless of inputs, c's balance is zero after go() (either call succeeded and forwarded, or the call reverted and no state change persisted).
        // This will hold for the reference contract for ALL inputs. The mutant that swallows the failed external call can leave funds in the contract for some inputs,
        // causing address(c).balance > 0 and thus making this assertion fail for those inputs.
        assertTrue(address(c).balance == 0);
    }
