pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz params: amount to send and a boolean deciding whether we route the call to a reverting callee
    function testFuzz_property(uint256 amount, bool useReverter) public {
        // keep amount in reasonable bounds and allow zero as well
        amount = bound(amount, 0, 1 ether);

        // deploy either a benign callee (that accepts funds) or a reverter (that reverts on receive)
        AcceptingReceiver accept = new AcceptingReceiver();
        RevertingReceiver reverter = new RevertingReceiver();

        address target = useReverter ? address(reverter) : address(accept);

        // fund the caller
        vm.deal(address(this), amount);

        // The contract C has the target address hard-coded; we cannot change it externally.
        // To route C's external call to our helper, we make the hard-coded target address be a contract
        // that forwards to our chosen helper. We do that by deploying a Forwarder at the exact hard-coded
        // address used in C. Foundry does not allow deploying to an arbitrary address directly in tests,
        // so instead we simulate the behaviour by making the hard-coded address be a contract we control
        // via creation using CREATE2 with the same address as in the original C source.
        // The address used in the original contract source is 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C

        // compute the address used in C and deploy a Forwarder there using CREATE2
        address desired = 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;

        // ensure slot is empty
        // deploy Forwarder with constructor target; Forwarder will forward calls to chosen target
        bytes memory forwarderBytecode = type(Forwarder).creationCode;
        bytes memory initCode = abi.encodePacked(forwarderBytecode, abi.encode(target));
        bytes32 salt = bytes32(uint256(uint160(desired))); // salt derived from desired address

        // If desired already has code, skip creation; otherwise create at that address via CREATE2 using selfdestruct trick
        // We'll deploy a DeployAt helper using CREATE2 to place Forwarder at desired
        DeployAt deployer = new DeployAt();
        deployer.deploy(initCode, salt);
        // now the address desired should have a Forwarder which forwards to our chosen target

        // call c.go forwarding the amount
        // Ensure the test contract has the ETH to send
        vm.deal(address(this), amount);

        bool ok;
        try c.go{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General fact: after go(), the reference C always forwards remaining balance to owner, so its balance is zero.
        // We assert that c's balance is zero — the reference satisfies this for all inputs; the mutant that ignores
        // a failing external call can leave non-zero balance for some inputs (useReverter = true and amount > 0).
        assertTrue(address(c).balance == 0);
    }
}

// Helper to deploy a contract at an arbitrary address via CREATE2
contract DeployAt {
    function deploy(bytes memory initCode, bytes32 salt) public returns (address addr) {
        assembly {
            addr := create2(0, add(initCode, 0x20), mload(initCode), salt)
            if iszero(extcodesize(addr)) { revert(0,0) }
        }
    }
}

// Forwarder: forwards any call and value to the target chosen at construction
contract Forwarder {
    address public target;
    constructor(address _t) payable {
        target = _t;
    }
    fallback() external payable {
        (bool s, ) = target.call{value: msg.value}(msg.data);
        if (!s) {
            // preserve revert to mimic direct call
            revert();
        }
    }
    receive() external payable {
        (bool s, ) = target.call{value: msg.value}("");
        if (!s) { revert(); }
    }
}

// benign accepting receiver
contract AcceptingReceiver {
    receive() external payable {}
}

// adversarial reverter
contract RevertingReceiver {
    receive() external payable {
        revert("revert");
    }
}

