contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz params: amount (uint128) and an address actor (to act as caller)
    function testFuzz_property(uint128 amount, address actor) public {
        // Keep amount wide but non-negative & bounded to avoid overflow in vm.deal
        uint256 amt = bound(uint256(amount), 0, 1 ether);
        // adversarial helper that reverts when receiving any nonzero value
        Reverter r = new Reverter();

        // fund the actor so they can send ETH
        vm.deal(actor, amt);
        // execute go from actor sending amt ether to c, routing c's hard-coded target to our Reverter
        // We cannot change c's hardcoded target address, but we can have Reverter live at that same address
        // in the test environment by deploying it at that address via CREATE2. However, we cannot control
        // deployment address here; instead, we use a different approach: the universal property we assert
        // is about whether c.go(...) reverts. The reference forwards msg.value to its hardcoded target; if
        // that target would revert on nonzero value, then c.go(...) reverts. We simulate that by making the
        // hardcoded target be an address that definitely reverts on nonzero value. To ensure the hardcoded
        // address in C points to a contract that reverts, we deploy a Reverter at that exact address using
        // a factory with CREATE2 and salt that yields the target address. We'll perform that deployment below.

        // deploy Reverter at address 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C using CREATE2
        bytes32 salt = bytes32(uint256(0xdeadbeef));
        bytes memory initCode = type(Reverter).creationCode;
        address targetAddr = 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;
        // Use a small factory to deploy at specific CREATE2 address that equals targetAddr
        // Compute expected address; if it doesn't match, we skip (assume) because we cannot force it.
        // Instead, we only proceed when the CREATE2 of this factory with given salt yields the targetAddr.
        Factory f = new Factory();
        // compute the address that the factory will produce
        address computed = f.computeAddress(salt, initCode);
        // require that computed equals the hardcoded target; otherwise this environment cannot emulate the adversary
        vm.assume(computed == targetAddr);
        // now actually deploy
        f.deploy{value: 0}(salt, initCode);

        // Now the hardcoded target in C points to Reverter which will revert on any nonzero value.
        bool ok;
        vm.prank(actor);
        try c.go{value: amt}() {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assert): If amt > 0 then the reference contract C forwards msg.value to the
        // hardcoded target which reverts on nonzero value, therefore the call should revert (ok == false).
        // The mutant that uses value:0 would not forward and therefore may return ok == true for some inputs.
        if (amt > 0) {
            assertTrue(!ok);
        } else {
            // amt == 0: both variants behave similarly (call with zero value); accept either outcome
            assertTrue(true);
        }
    }
}

contract Factory {
    event Deployed(address addr);
    function deploy(bytes32 salt, bytes memory initCode) external returns (address addr) {
        assembly {
            addr := create2(0, add(initCode, 0x20), mload(initCode), salt)
        }
        emit Deployed(addr);
    }
    function computeAddress(bytes32 salt, bytes memory initCode) external view returns (address) {
        bytes32 hash = keccak256(abi.encodePacked(bytes1(0xff), address(this), salt, keccak256(initCode)));
        return address(uint160(uint256(hash)));
    }
}

contract Reverter {
    fallback() external payable {
        // revert if any nonzero value received
        if (msg.value > 0) revert("no value");
    }
}

